DROP TABLE IF EXISTS `books`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `books` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `cover` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `language` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `adder_id` int(11) NOT NULL,
  `active` tinyint(1) NOT NULL,
  `unauthorized_views_count` int(11) NOT NULL,
  `authorized_views_count` int(11) NOT NULL,
  `unauthorized_downloads_count` int(11) NOT NULL,
  `authorized_downloads_count` int(11) NOT NULL,
  `likes_count` int(11) NOT NULL,
  `rating` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `authors_names` text COLLATE utf8mb4_unicode_ci,
  `redirect` int(11) DEFAULT NULL,
  `alias` text COLLATE utf8mb4_unicode_ci,
  `reads_count` int(11) DEFAULT NULL,
  `preview` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5353 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

